type UserPositionsClockKey struct {
	User    common.Address
	TokenID common.Hash
}

func NewUserPositionsClockKey(value MemoryUserPosition) UserPositionsClockKey {
	return UserPositionsClockKey{User: value.User, TokenID: value.TokenID}
}

type UserPositionsClockEntry struct {
	key        UserPositionsClockKey
	value      MemoryUserPosition
	referenced uint32
	inUse      uint32
}

type UserPositionsClockCache struct {
	buckets  []int32
	next     []int32
	ring     []UserPositionsClockEntry
	mask     uint32
	capacity uint64
	hand     uint64
	size     uint64
	// evictions counts entries overwritten by CLOCK replacement. While zero,
	// the hot ring still holds everything ever Set — so under an authoritative
	// (from-genesis) run, hot contents are a superset of the entity's
	// ClickHouse rows and a hot miss proves a database miss.
	evictions uint64
	// cold is an optional Pebble-backed tier holding evicted entries (raw bytes).
	// nil unless attached via HotState.EnableColdCache (pointer-free entities only).
	cold *coldcache.Store
}

// Evictions reports how many entries CLOCK replacement has overwritten.
func (c *UserPositionsClockCache) Evictions() uint64 {
	return atomic.LoadUint64(&c.evictions)
}

func NewUserPositionsClockCache(capacity uint64) *UserPositionsClockCache {
	if capacity == 0 {
		capacity = DefaultClockCacheCapacity
	}
	bucketCount := uint64(8)
	for bucketCount < capacity*2 {
		bucketCount <<= 1
	}
	c := &UserPositionsClockCache{
		ring:     make([]UserPositionsClockEntry, capacity),
		buckets:  make([]int32, bucketCount),
		next:     make([]int32, capacity),
		mask:     uint32(bucketCount - 1),
		capacity: capacity,
	}
	for i := range c.buckets {
		c.buckets[i] = -1
	}
	for i := range c.next {
		c.next[i] = -1
	}
	return c
}

func (c *UserPositionsClockCache) keyHash(key UserPositionsClockKey) uint32 {
	h := uint64(1469598103934665603)
	h = clockHash64(h, key.User[:])
	h = clockHash64(h, key.TokenID[:])
	return uint32(h^(h>>32)) & c.mask
}

func (c *UserPositionsClockCache) idxLookup(key UserPositionsClockKey) (uint64, bool) {
	for i := c.buckets[c.keyHash(key)]; i >= 0; i = c.next[i] {
		if c.ring[i].key == key {
			return uint64(i), true
		}
	}
	return 0, false
}

func (c *UserPositionsClockCache) idxInsert(key UserPositionsClockKey, ringIdx uint32) {
	h := c.keyHash(key)
	c.next[ringIdx] = c.buckets[h]
	c.buckets[h] = int32(ringIdx)
}

func (c *UserPositionsClockCache) idxUnlink(key UserPositionsClockKey) {
	h := c.keyHash(key)
	prev := int32(-1)
	for i := c.buckets[h]; i >= 0; i = c.next[i] {
		if c.ring[i].key == key {
			if prev < 0 {
				c.buckets[h] = c.next[i]
			} else {
				c.next[prev] = c.next[i]
			}
			c.next[i] = -1
			return
		}
		prev = i
	}
}

func (c *UserPositionsClockCache) Set(value MemoryUserPosition) {
	c.SetByKey(NewUserPositionsClockKey(value), value)
}

func (c *UserPositionsClockCache) SetByKey(key UserPositionsClockKey, value MemoryUserPosition) {
	if idx, ok := c.idxLookup(key); ok {
		e := &c.ring[idx]
		if atomic.LoadUint32(&e.inUse) == 1 && e.key == key {
			e.value = value
			atomic.StoreUint32(&e.referenced, 1)
			return
		}
	}
	for {
		hand := atomic.AddUint64(&c.hand, 1)
		idx := (hand - 1) % c.capacity
		e := &c.ring[idx]
		if atomic.CompareAndSwapUint32(&e.inUse, 1, 0) {
			if atomic.LoadUint32(&e.referenced) == 1 {
				atomic.StoreUint32(&e.referenced, 0)
				atomic.StoreUint32(&e.inUse, 1)
				continue
			}
			if c.cold != nil {
				c.cold.Put(unsafe.Slice((*byte)(unsafe.Pointer(&e.key)), unsafe.Sizeof(e.key)), unsafe.Slice((*byte)(unsafe.Pointer(&e.value)), unsafe.Sizeof(e.value)))
			}
			atomic.AddUint64(&c.evictions, 1)
			c.idxUnlink(e.key)
			e.key = key
			e.value = value
			atomic.StoreUint32(&e.referenced, 0)
			c.idxInsert(key, uint32(idx))
			atomic.StoreUint32(&e.inUse, 1)
			return
		}
		if atomic.LoadUint32(&e.inUse) == 0 {
			if atomic.CompareAndSwapUint32(&e.inUse, 0, 2) {
				e.key = key
				e.value = value
				atomic.StoreUint32(&e.referenced, 0)
				c.idxInsert(key, uint32(idx))
				atomic.AddUint64(&c.size, 1)
				atomic.StoreUint32(&e.inUse, 1)
				return
			}
		}
	}
}

func (c *UserPositionsClockCache) Get(key UserPositionsClockKey) (MemoryUserPosition, bool) {
	if idx, ok := c.idxLookup(key); ok {
		e := &c.ring[idx]
		if atomic.LoadUint32(&e.inUse) == 1 && e.key == key {
			atomic.StoreUint32(&e.referenced, 1)
			return e.value, true
		}
	}
	if c.cold != nil {
		var v MemoryUserPosition
		if found, _ := c.cold.GetInto(unsafe.Slice((*byte)(unsafe.Pointer(&v)), unsafe.Sizeof(v)), unsafe.Slice((*byte)(unsafe.Pointer(&key)), unsafe.Sizeof(key))); found {
			c.SetByKey(key, v)
			return v, true
		}
	}
	return MemoryUserPosition{}, false
}

func (c *UserPositionsClockCache) GetByFields(user common.Address, tokenID common.Hash) (MemoryUserPosition, bool) {
	return c.Get(UserPositionsClockKey{User: user, TokenID: tokenID})
}

func (c *UserPositionsClockCache) Delete(key UserPositionsClockKey) bool {
	idx, ok := c.idxLookup(key)
	if !ok {
		return false
	}
	e := &c.ring[idx]
	if atomic.CompareAndSwapUint32(&e.inUse, 1, 0) {
		if e.key == key {
			c.idxUnlink(key)
			if c.cold != nil {
				c.cold.Delete(unsafe.Slice((*byte)(unsafe.Pointer(&key)), unsafe.Sizeof(key)))
			}
			e.key = UserPositionsClockKey{}
			e.value = MemoryUserPosition{}
			atomic.StoreUint32(&e.referenced, 0)
			atomic.AddUint64(&c.size, ^uint64(0))
			return true
		}
		atomic.StoreUint32(&e.inUse, 1)
	}
	return false
}

func (c *UserPositionsClockCache) Range(fn func(UserPositionsClockKey, MemoryUserPosition) bool) {
	if fn == nil {
		return
	}
	limit := atomic.LoadUint64(&c.hand)
	if limit > c.capacity {
		limit = c.capacity
	}
	for i := uint64(0); i < limit; i++ {
		e := &c.ring[i]
		if atomic.LoadUint32(&e.inUse) == 1 {
			if !fn(e.key, e.value) {
				return
			}
		}
	}
}

func (c *UserPositionsClockCache) AppendValues(dst []MemoryUserPosition) []MemoryUserPosition {
	if c == nil {
		return dst
	}
	if atomic.LoadUint64(&c.size) == 0 {
		return dst
	}
	limit := atomic.LoadUint64(&c.hand)
	if limit > c.capacity {
		limit = c.capacity
	}
	for i := 0; i < int(limit); i++ {
		e := &c.ring[i]
		if atomic.LoadUint32(&e.inUse) == 1 {
			dst = append(dst, e.value)
		}
	}
	return dst
}

func (c *UserPositionsClockCache) Len() uint64 {
	return atomic.LoadUint64(&c.size)
}

