type ConditionPreparationsClockKey struct {
	ConditionID common.Hash
}

func NewConditionPreparationsClockKey(value ConditionalTokensConditionPreparation) ConditionPreparationsClockKey {
	return ConditionPreparationsClockKey{ConditionID: value.ConditionID}
}

type ConditionPreparationsClockEntry struct {
	key        ConditionPreparationsClockKey
	value      ConditionalTokensConditionPreparation
	referenced uint32
	inUse      uint32
}

type ConditionPreparationsClockCache struct {
	buckets  []int32
	next     []int32
	ring     []ConditionPreparationsClockEntry
	mask     uint32
	capacity uint64
	hand     uint64
	size     uint64
	// evictions counts entries overwritten by CLOCK replacement. While zero,
	// the hot ring still holds everything ever Set — so under an authoritative
	// (from-genesis) run, hot contents are a superset of the entity's
	// ClickHouse rows and a hot miss proves a database miss.
	evictions uint64
	// cold is an optional Pebble-backed tier holding evicted entries (raw bytes).
	// nil unless attached via HotState.EnableColdCache (pointer-free entities only).
	cold *coldcache.Store
}

// Evictions reports how many entries CLOCK replacement has overwritten.
func (c *ConditionPreparationsClockCache) Evictions() uint64 {
	return atomic.LoadUint64(&c.evictions)
}

func NewConditionPreparationsClockCache(capacity uint64) *ConditionPreparationsClockCache {
	if capacity == 0 {
		capacity = DefaultClockCacheCapacity
	}
	bucketCount := uint64(8)
	for bucketCount < capacity*2 {
		bucketCount <<= 1
	}
	c := &ConditionPreparationsClockCache{
		ring:     make([]ConditionPreparationsClockEntry, capacity),
		buckets:  make([]int32, bucketCount),
		next:     make([]int32, capacity),
		mask:     uint32(bucketCount - 1),
		capacity: capacity,
	}
	for i := range c.buckets {
		c.buckets[i] = -1
	}
	for i := range c.next {
		c.next[i] = -1
	}
	return c
}

func (c *ConditionPreparationsClockCache) keyHash(key ConditionPreparationsClockKey) uint32 {
	h := uint64(1469598103934665603)
	h = clockHash64(h, key.ConditionID[:])
	return uint32(h^(h>>32)) & c.mask
}

func (c *ConditionPreparationsClockCache) idxLookup(key ConditionPreparationsClockKey) (uint64, bool) {
	for i := c.buckets[c.keyHash(key)]; i >= 0; i = c.next[i] {
		if c.ring[i].key == key {
			return uint64(i), true
		}
	}
	return 0, false
}

func (c *ConditionPreparationsClockCache) idxInsert(key ConditionPreparationsClockKey, ringIdx uint32) {
	h := c.keyHash(key)
	c.next[ringIdx] = c.buckets[h]
	c.buckets[h] = int32(ringIdx)
}

func (c *ConditionPreparationsClockCache) idxUnlink(key ConditionPreparationsClockKey) {
	h := c.keyHash(key)
	prev := int32(-1)
	for i := c.buckets[h]; i >= 0; i = c.next[i] {
		if c.ring[i].key == key {
			if prev < 0 {
				c.buckets[h] = c.next[i]
			} else {
				c.next[prev] = c.next[i]
			}
			c.next[i] = -1
			return
		}
		prev = i
	}
}

func (c *ConditionPreparationsClockCache) Set(value ConditionalTokensConditionPreparation) {
	c.SetByKey(NewConditionPreparationsClockKey(value), value)
}

func (c *ConditionPreparationsClockCache) SetByKey(key ConditionPreparationsClockKey, value ConditionalTokensConditionPreparation) {
	if idx, ok := c.idxLookup(key); ok {
		e := &c.ring[idx]
		if atomic.LoadUint32(&e.inUse) == 1 && e.key == key {
			e.value = value
			atomic.StoreUint32(&e.referenced, 1)
			return
		}
	}
	for {
		hand := atomic.AddUint64(&c.hand, 1)
		idx := (hand - 1) % c.capacity
		e := &c.ring[idx]
		if atomic.CompareAndSwapUint32(&e.inUse, 1, 0) {
			if atomic.LoadUint32(&e.referenced) == 1 {
				atomic.StoreUint32(&e.referenced, 0)
				atomic.StoreUint32(&e.inUse, 1)
				continue
			}
			atomic.AddUint64(&c.evictions, 1)
			c.idxUnlink(e.key)
			e.key = key
			e.value = value
			atomic.StoreUint32(&e.referenced, 0)
			c.idxInsert(key, uint32(idx))
			atomic.StoreUint32(&e.inUse, 1)
			return
		}
		if atomic.LoadUint32(&e.inUse) == 0 {
			if atomic.CompareAndSwapUint32(&e.inUse, 0, 2) {
				e.key = key
				e.value = value
				atomic.StoreUint32(&e.referenced, 0)
				c.idxInsert(key, uint32(idx))
				atomic.AddUint64(&c.size, 1)
				atomic.StoreUint32(&e.inUse, 1)
				return
			}
		}
	}
}

func (c *ConditionPreparationsClockCache) Get(key ConditionPreparationsClockKey) (ConditionalTokensConditionPreparation, bool) {
	idx, ok := c.idxLookup(key)
	if !ok {
		return ConditionalTokensConditionPreparation{}, false
	}
	e := &c.ring[idx]
	if atomic.LoadUint32(&e.inUse) == 1 && e.key == key {
		atomic.StoreUint32(&e.referenced, 1)
		return e.value, true
	}
	return ConditionalTokensConditionPreparation{}, false
}

func (c *ConditionPreparationsClockCache) GetByFields(conditionID common.Hash) (ConditionalTokensConditionPreparation, bool) {
	return c.Get(ConditionPreparationsClockKey{ConditionID: conditionID})
}

func (c *ConditionPreparationsClockCache) Delete(key ConditionPreparationsClockKey) bool {
	idx, ok := c.idxLookup(key)
	if !ok {
		return false
	}
	e := &c.ring[idx]
	if atomic.CompareAndSwapUint32(&e.inUse, 1, 0) {
		if e.key == key {
			c.idxUnlink(key)
			e.key = ConditionPreparationsClockKey{}
			e.value = ConditionalTokensConditionPreparation{}
			atomic.StoreUint32(&e.referenced, 0)
			atomic.AddUint64(&c.size, ^uint64(0))
			return true
		}
		atomic.StoreUint32(&e.inUse, 1)
	}
	return false
}

